package com.vandorlabs.gear.core;
import java.util.*;
/** Independent released loops and float steps, including complete cached reservation ordering. */
public final class LegacyLandingPolicyTest {
 private static int checks;private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 public static void main(String[] args){for(int size=0;size<5;size++)for(int pixel=0;pixel<=64;pixel+=8){float end=pixel/16F,p=0;for(int tick=0;tick<81;tick++){float expected=p<end?Math.min(end,p+.05F):Math.max(end,p-.05F);need(Float.floatToIntBits(LegacyLandingSettings.advance(p,end))==Float.floatToIntBits(expected),"Source float advance");p=expected;}need(p==end,"endpoint reached");java.util.List<LegacyLandingLayout.Offset> cells=LegacyLandingLayout.reserved(end,size);List<String> expected=new ArrayList<String>();int depth=(int)Math.ceil(end)+(size>=3?1:0),radius=size>=3?1:0,min=size==4?0:-radius;for(int y=0;y<=depth;y++)for(int x=min;x<=radius;x++)for(int z=min;z<=radius;z++)if(y!=0||x!=0||z!=0)expected.add(x+","+-y+","+z);need(cells.size()==expected.size()&&cells.size()<=LegacyLandingLayout.MAX_CELLS,"footprint count");for(int i=0;i<cells.size();i++){LegacyLandingLayout.Offset o=cells.get(i);need(expected.get(i).equals(o.x+","+o.y+","+o.z),"Source footprint order");need(LegacyLandingLayout.ownerOffset(-o.x,-o.y,-o.z),"owned proxy offset bounds");}need(cells==LegacyLandingLayout.reserved(end,size),"cached immutable reuse");for(int y=0;y<=5;y++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){boolean kept=y<=Math.ceil(end)+(radius==1?1:0)&&Math.abs(x)<=radius&&Math.abs(z)<=radius&&(size!=4||x>=0&&z>=0)&&(y>0||radius==1);need(LegacyLandingLayout.kept(y,x,z,(int)Math.ceil(end),size)==kept,"Source release predicate");}}
 for(int value=-80;value<=160;value++){need(LegacyLandingSettings.pixels(true,value)==Math.round(Math.max(0,Math.min(64,value))/8F)*8,"released pixel clamp");need(LegacyLandingSettings.mode(true,value)==Math.max(0,Math.min(2,value)),"released mode clamp");}need(LegacyLandingSettings.pixels(false,0)==16&&LegacyLandingSettings.mode(false,0)==1,"released missing defaults");for(int a=0;a<4;a++)for(int b=0;b<4;b++)need(LegacyLandingLayout.connectedEnd(true,true,4,4,a,b,2,2)==((a&1)==(b&1)),"axis parity");System.out.println("Legacy landing policy PASS checks="+checks);}
 private LegacyLandingPolicyTest(){}
}
